INSERT INTO `proposals` VALUES (170,'Fit for 55 - Paket, European Green Deal, REPower-EU-Plan, RED III','2025-05-15 22:15:00'),(171,'CRR, CRD, Basel and other financial and banking regulations regarding capital adequacy, consumer protections etc','2025-05-15 22:15:00'),(172,'- guide bleu','2025-05-15 22:15:01'),(173,'- règlement européen relatif aux installations à câbles','2025-05-15 22:15:01'),(174,'- tout texte relatif aux installations à câbles et à leur sécurité','2025-05-15 22:15:01'),(175,'- tout texte relatif aux règles s\'imposant aux organismes notifiés','2025-05-15 22:15:01'),(176,'EIP-Agri Subgroup of Innovation','2025-05-15 22:15:01'),(177,'Horizon 2020','2025-05-15 22:15:01'),(178,'Landsbygdsprogrammet Sverige 2014-2020','2025-05-15 22:15:01'),(179,'Smart Specialisering i regioner','2025-05-15 22:15:01'),(180,'1	Communication on The European Green Deal, including the Circular Economy Action Plan 20','2025-05-15 22:15:02'),(181,'2	Directive 2008/98/EC of the European Parliament and of the Council of 19 November 2008 on waste and repealing certain Directives','2025-05-15 22:15:02'),(182,'3	Regulation (EU) 2025/40 of the European Parliament and of the Council of 19 December 2024 on packaging and packaging waste, amending Regulation (EU) 2019/1020 and Directive (EU) 2019/904, and repealing Directive 94/62/EC','2025-05-15 22:15:02'),(183,'4	Regulation (EU) 2024/1157 of the European Parliament and of the Council of 11 April 2024 on shipments of waste, amending Regulations (EU) No 1257/2013 and (EU) 2020/1056 and repealing Regulation (EC) No 1013/2006','2025-05-15 22:15:02'),(184,'5	Directive (EU) 2019/904 of the European Parliament and of the Council on the reduction of the impact of certain plastic products on the environment','2025-05-15 22:15:02'),(185,'6	Proposal for a Directive of the European Parliament and of the Council on substantiation and communication of explicit environmental claims (Green Claims Directive)','2025-05-15 22:15:02'),(186,'7	Regula